namespace sv_fc4ea6ef8019433392c44917b3f8879f.Client.Models;

public sealed record ShipmentDetails(
    string TrackingNumber,
    string Status,
    string Location,
    DateTimeOffset EstimatedDelivery,
    IReadOnlyList<StatusUpdate> StatusUpdates);

public sealed record StatusUpdate(
    string Status,
    string Location,
    DateTimeOffset Timestamp);

using sv_fc4ea6ef8019433392c44917b3f8879f.Client.Models;

namespace sv_fc4ea6ef8019433392c44917b3f8879f.Client.Services;

public interface IShipmentService
{
    Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using sv_fc4ea6ef8019433392c44917b3f8879f.Client.Models;
using sv_fc4ea6ef8019433392c44917b3f8879f.Client.Services;

namespace sv_fc4ea6ef8019433392c44917b3f8879f.Services;

public sealed class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, ShipmentDetails> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-1001"] = new ShipmentDetails(
            TrackingNumber: "TRK-1001",
            Status: "In Transit",
            Location: "Chicago, IL",
            EstimatedDelivery: new DateTimeOffset(2026, 7, 5, 17, 0, 0, TimeSpan.Zero),
            StatusUpdates:
            [
                new StatusUpdate("Order Placed", "New York, NY", new DateTimeOffset(2026, 6, 28, 10, 0, 0, TimeSpan.Zero)),
                new StatusUpdate("Picked Up", "New York, NY", new DateTimeOffset(2026, 6, 29, 8, 30, 0, TimeSpan.Zero)),
                new StatusUpdate("In Transit", "Chicago, IL", new DateTimeOffset(2026, 6, 30, 14, 15, 0, TimeSpan.Zero)),
            ]),

        ["TRK-2002"] = new ShipmentDetails(
            TrackingNumber: "TRK-2002",
            Status: "Delivered",
            Location: "San Francisco, CA",
            EstimatedDelivery: new DateTimeOffset(2026, 6, 30, 12, 0, 0, TimeSpan.Zero),
            StatusUpdates:
            [
                new StatusUpdate("Order Placed", "Seattle, WA", new DateTimeOffset(2026, 6, 25, 9, 0, 0, TimeSpan.Zero)),
                new StatusUpdate("Shipped", "Seattle, WA", new DateTimeOffset(2026, 6, 26, 11, 0, 0, TimeSpan.Zero)),
                new StatusUpdate("In Transit", "Portland, OR", new DateTimeOffset(2026, 6, 27, 16, 45, 0, TimeSpan.Zero)),
                new StatusUpdate("Out for Delivery", "San Francisco, CA", new DateTimeOffset(2026, 6, 29, 7, 0, 0, TimeSpan.Zero)),
                new StatusUpdate("Delivered", "San Francisco, CA", new DateTimeOffset(2026, 6, 29, 14, 22, 0, TimeSpan.Zero)),
            ]),

        ["TRK-3003"] = new ShipmentDetails(
            TrackingNumber: "TRK-3003",
            Status: "Out for Delivery",
            Location: "Austin, TX",
            EstimatedDelivery: new DateTimeOffset(2026, 7, 1, 18, 0, 0, TimeSpan.Zero),
            StatusUpdates:
            [
                new StatusUpdate("Order Placed", "Miami, FL", new DateTimeOffset(2026, 6, 27, 12, 0, 0, TimeSpan.Zero)),
                new StatusUpdate("Shipped", "Miami, FL", new DateTimeOffset(2026, 6, 28, 6, 0, 0, TimeSpan.Zero)),
                new StatusUpdate("In Transit", "Houston, TX", new DateTimeOffset(2026, 6, 29, 22, 0, 0, TimeSpan.Zero)),
                new StatusUpdate("Out for Delivery", "Austin, TX", new DateTimeOffset(2026, 7, 1, 8, 0, 0, TimeSpan.Zero)),
            ]),
    };

    public async Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);

        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

using System.Net;
using System.Net.Http.Json;
using sv_fc4ea6ef8019433392c44917b3f8879f.Client.Models;

namespace sv_fc4ea6ef8019433392c44917b3f8879f.Client.Services;

public sealed class ClientShipmentService(HttpClient httpClient) : IShipmentService
{
    public async Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var encodedTrackingNumber = Uri.EscapeDataString(trackingNumber);
        using var response = await httpClient.GetAsync($"api/shipments/{encodedTrackingNumber}", ct);

        if (response.StatusCode == HttpStatusCode.NotFound)
            return null;

        response.EnsureSuccessStatusCode();

        return await response.Content.ReadFromJsonAsync<ShipmentDetails>(ct);
    }
}

@page "/shipments/{TrackingNumber}"
@using sv_fc4ea6ef8019433392c44917b3f8879f.Client.Models
@using sv_fc4ea6ef8019433392c44917b3f8879f.Client.Services
@rendermode InteractiveAuto
@implements IDisposable
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracker> Logger

<PageTitle>Shipment @TrackingNumber</PageTitle>

<h2>Shipment Tracking</h2>

@if (_loading)
{
    <div class="loading-placeholder">
        <p><em>Loading shipment details for @TrackingNumber&hellip;</em></p>
    </div>
}
else if (_errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <p>@_errorMessage</p>
        <button class="btn btn-outline-danger" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_shipment is null)
{
    <div class="alert alert-warning" role="alert">
        <p>No shipment found for tracking number <strong>@TrackingNumber</strong>.</p>
    </div>
}
else
{
    <div class="shipment-details">
        <dl>
            <dt>Tracking Number</dt>
            <dd>@_shipment.TrackingNumber</dd>

            <dt>Status</dt>
            <dd>@_shipment.Status</dd>

            <dt>Current Location</dt>
            <dd>@_shipment.Location</dd>

            <dt>Estimated Delivery</dt>
            <dd>@_shipment.EstimatedDelivery.ToString("f")</dd>
        </dl>

        <h3>Status History</h3>
        <table class="table">
            <thead>
                <tr>
                    <th>Timestamp</th>
                    <th>Status</th>
                    <th>Location</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var update in _shipment.StatusUpdates)
                {
                    <tr>
                        <td>@update.Timestamp.ToString("g")</td>
                        <td>@update.Status</td>
                        <td>@update.Location</td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = default!;

    private ShipmentDetails? _shipment;
    private bool _loading;
    private string? _errorMessage;

    private CancellationTokenSource? _cts;
    private string? _loadedTrackingNumber;

    protected override async Task OnParametersSetAsync()
    {
        if (string.Equals(_loadedTrackingNumber, TrackingNumber, StringComparison.OrdinalIgnoreCase) && !_loading)
            return;

        await LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        // Cancel any in-flight request for a previous tracking number.
        await CancelPendingRequestAsync();

        _cts = new CancellationTokenSource();
        _loadedTrackingNumber = TrackingNumber;
        _shipment = null;
        _errorMessage = null;
        _loading = true;

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, _cts.Token);
        }
        catch (OperationCanceledException)
        {
            // Request was intentionally cancelled — nothing to show.
            return;
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (TaskCanceledException ex) when (ex.InnerException is TimeoutException)
        {
            Logger.LogError(ex, "HTTP timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "Something went wrong while loading shipment details. Please try again.";
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task RetryAsync()
    {
        await LoadShipmentAsync();
    }

    private async Task CancelPendingRequestAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
            _cts = null;
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }
}

